     1→/**
     2→ * FreeLang Nexus - 통합 Parser
     3→ * V 모드 + Python 모드 함수를 혼합하여 파싱
     4→ */
     5→
     6→import { Token, TokenType } from '../lexer/token';
     7→import * as AST from './ast';
     8→
     9→export class NexusParser {
    10→  private tokens: Token[];
    11→  private pos: number = 0;
    12→
    13→  constructor(tokens: Token[]) {
    14→    this.tokens = tokens;
    15→  }
    16→
    17→  /**
    18→   * 파싱 진입점
    19→   */
    20→  parse(): AST.Program {
    21→    const body: Array<AST.VFunction | AST.PyFunction | AST.StructDef | AST.Statement> = [];
    22→
    23→    while (!this.isAtEnd()) {
    24→      this.skipNewlines();
    25→      if (this.isAtEnd()) break;
    26→
    27→      const token = this.peek();
    28→
    29→      // @mode 마커는 스킵 (이미 렉서에서 처리됨)
    30→      if (token.type === TokenType.MODE_MARKER) {
    31→        this.advance();
    32→        continue;
    33→      }
    34→
    35→      // 탑레벨 아이템 파싱
    36→      const item = this.parseTopLevel();
    37→      if (item) {
    38→        body.push(item);
    39→      }
    40→    }
    41→
    42→    return { type: 'Program', body };
    43→  }
    44→
    45→  /**
    46→   * 탑레벨 아이템 파싱
    47→   * V 함수, Python 함수, 구조체, 또는 문장
    48→   */
    49→  private parseTopLevel(): AST.VFunction | AST.PyFunction | AST.StructDef | AST.Statement | null {
    50→    const token = this.peek();
    51→
    52→    // V 모드 함수
    53→    if (token.type === TokenType.FN) {
    54→      return this.parseVFunction();
    55→    }
    56→
    57→    // Python 모드 함수
    58→    if (token.type === TokenType.DEF) {
    59→      return this.parsePyFunction();
    60→    }
    61→
    62→    // 구조체 정의
    63→    if (token.type === TokenType.STRUCT) {
    64→      return this.parseStructDef();
    65→    }
    66→
    67→    // 그 외: 문장
    68→    return this.parseStatement();
    69→  }
    70→
    71→  /**
    72→   * V 함수 파싱
    73→   * fn name(params) -> type { body }
    74→   */
    75→  private parseVFunction(): AST.VFunction {
    76→    const startToken = this.consume(TokenType.FN, 'fn 키워드 필요');
    77→    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
    78→    const name = nameToken.value;
    79→
    80→    this.consume(TokenType.LPAREN, '( 필요');
    81→    const params = this.parseVParams();
    82→    this.consume(TokenType.RPAREN, ') 필요');
    83→
    84→    const returnType = this.parseReturnType();
    85→
    86→    this.consume(TokenType.LBRACE, '{ 필요');
    87→    const body = this.parseVBlock();
    88→    this.consume(TokenType.RBRACE, '} 필요');
    89→
    90→    return {
    91→      type: 'VFunction',
    92→      name,
    93→      params,
    94→      returnType,
    95→      body,
    96→      mode: 'v',
    97→      line: startToken.line,
    98→      column: startToken.column,
    99→    };
