    const c = compile(`@mode(v)
fn test() -> i64 {
  let nums = [1, 2, 3]
  return 0
}`);
    expect(c).toContain('long long nums[3]');
    expect(c).toContain('{1, 2, 3}');
  });

  test('Test 7: 명시적 i64[] 타입 어노테이션', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let nums: i64[] = [10, 20, 30]
  return 0
}`);
    expect(c).toContain('long long nums[3]');
    expect(c).toContain('{10, 20, 30}');
  });

  test('Test 8: 배열 인덱싱 코드젠', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let nums: i64[] = [1, 2, 3]
  return nums[0]
}`);
    expect(c).toContain('nums[0]');
  });

  test('Test 9: for-in range + println 조합', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  for i in range(3) {
    println(i)
  }
  return 0
}`);
    expect(c).toContain('for (long long i = 0; i < 3; i++)');
    expect(c).toContain('printf("%lld\\n", i)');
  });

  test('Test 10: 빈 배열 + 명시적 타입 어노테이션 AST', () => {
    const lexer = new NexusLexer(`@mode(v)
fn test() -> i64 {
  let empty: i64[] = []
  return 0
}`);
    const ast = new NexusParser(lexer.tokenize()).parse();
    const fn = ast.body[0] as any;
    const assign = fn.body[0] as any;
    expect(assign.type).toBe('Assign');
    expect(assign.typeAnnotation).toBe('i64[]');
    expect(assign.value.type).toBe('Array');
    expect(assign.value.elements.length).toBe(0);
  });
});

// ─── stdlib 수학 ──────────────────────────────────────────────────────────────

describe('Phase N.4 - stdlib 수학 함수', () => {
  test('Test 11: abs(x) → llabs(x)', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return abs(-42)
}`);
    expect(c).toContain('llabs(-42)');
  });

  test('Test 12: min(a, b) → 삼항 연산자', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return min(3, 7)
}`);
    expect(c).toContain('(3) < (7) ? (3) : (7)');
  });

  test('Test 13: max(a, b) → 삼항 연산자', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return max(10, 5)
}`);
    expect(c).toContain('(10) > (5) ? (10) : (5)');
  });

  test('Test 14: sqrt(x) → sqrt((double)(x))', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return sqrt(16)
}`);
    expect(c).toContain('sqrt((double)(16))');
  });

  test('Test 15: pow(base, exp) → pow(...)', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return pow(2, 10)
}`);
    expect(c).toContain('pow((double)(2), (double)(10))');
  });

  test('Test 16: floor + ceil 코드젠', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let a = floor(3)
  let b = ceil(3)
  return 0
}`);
    expect(c).toContain('floor((double)(3))');
    expect(c).toContain('ceil((double)(3))');
  });
});

// ─── stdlib 문자열 ────────────────────────────────────────────────────────────

describe('Phase N.4 - stdlib 문자열 함수', () => {
  test('Test 17: str_len(s) → strlen(s)', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return str_len("hello")
}`);
    expect(c).toContain('strlen("hello")');
  });

  test('Test 18: str_contains(s, sub) → strstr != NULL', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return str_contains("hello world", "world")
}`);
    expect(c).toContain('strstr(');
    expect(c).toContain('!= NULL');
  });

  test('Test 19: str_eq(a, b) → strcmp == 0', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return str_eq("abc", "abc")
}`);
    expect(c).toContain('strcmp(');
    expect(c).toContain('== 0');
  });

  test('Test 20: float_cast + bool_cast 코드젠', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let f = float_cast(42)
  let b = bool_cast(1)
  return 0
}`);
    expect(c).toContain('(double)(42)');
    expect(c).toContain('(bool)(1)');
  });
});

