   315→  private tokenizeOperator(): Token | null {
   316→    const ch = this.peek();
   317→    const next = this.peek(1);
   318→    const next2 = this.peek(2);
   319→
   320→    // 3글자 연산자
   321→    if (ch === '.' && next === '.' && next2 === '=') {
   322→      this.advance();
   323→      this.advance();
   324→      this.advance();
   325→      return this.makeToken(TokenType.IDENTIFIER, '..=', this.currentMode); // 커스텀
   326→    }
   327→
   328→    // 2글자 연산자
   329→    const twoChar = ch && next ? ch + next : '';
   330→    const twoCharMap: Record<string, TokenType> = {
   331→      '->': TokenType.ARROW,
   332→      '=>': TokenType.IDENTIFIER, // FatArrow (커스텀)
   333→      '==': TokenType.EQ,
   334→      '!=': TokenType.NE,
   335→      '<=': TokenType.LE,
   336→      '>=': TokenType.GE,
   337→      '&&': TokenType.AND,
   338→      '||': TokenType.OR,
   339→      '::': TokenType.IDENTIFIER, // DoubleColon (커스텀)
   340→      '..': TokenType.IDENTIFIER, // DotDot (커스텀)
   341→      '//': TokenType.SLASH, // 이미 주석 처리됨
   342→      '**': TokenType.STAR, // Power (커스텀)
   343→    };
   344→
   345→    if (twoCharMap[twoChar]) {
   346→      this.advance();
   347→      this.advance();
   348→      return this.makeToken(twoCharMap[twoChar], twoChar, this.currentMode);
   349→    }
   350→
   351→    // 1글자 연산자
   352→    const oneCharMap: Record<string, TokenType> = {
   353→      '(': TokenType.LPAREN,
   354→      ')': TokenType.RPAREN,
   355→      '{': TokenType.LBRACE,
   356→      '}': TokenType.RBRACE,
   357→      '[': TokenType.LBRACKET,
   358→      ']': TokenType.RBRACKET,
   359→      ',': TokenType.COMMA,
   360→      '.': TokenType.DOT,
   361→      ';': TokenType.SEMICOLON,
   362→      ':': TokenType.COLON,
   363→      '=': TokenType.EQUAL,
   364→      '+': TokenType.PLUS,
   365→      '-': TokenType.MINUS,
   366→      '*': TokenType.STAR,
   367→      '/': TokenType.SLASH,
   368→      '%': TokenType.PERCENT,
   369→      '<': TokenType.LT,
   370→      '>': TokenType.GT,
   371→      '!': TokenType.NOT,
   372→      '&': TokenType.AMPERSAND,
   373→      '|': TokenType.PIPE,
   374→      '@': TokenType.AT,
   375→    };
   376→
   377→    if (ch && oneCharMap[ch]) {
   378→      this.advance();
   379→      return this.makeToken(oneCharMap[ch], ch, this.currentMode);
   380→    }
   381→
   382→    return null;
   383→  }
   384→
   385→  /**
   386→   * @mode() 디렉티브 파싱
   387→   */
   388→  private tryParseMode(): Token | null {
   389→    const start = this.pos;
   390→
   391→    if (this.peek() !== '@') {
   392→      return null;
   393→    }
   394→
   395→    this.advance(); // '@'
   396→
   397→    // @mode 확인
   398→    if (
   399→      this.peek() === 'm' &&
   400→      this.peek(1) === 'o' &&
   401→      this.peek(2) === 'd' &&
   402→      this.peek(3) === 'e'
   403→    ) {
   404→      this.advance();
   405→      this.advance();
   406→      this.advance();
   407→      this.advance();
   408→
   409→      // 공백 및 ( 확인
   410→      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   411→        this.advance();
   412→      }
   413→
   414→      if (this.peek() !== '(') {
   415→        // @mode가 아니면 다시 돌아가기
   416→        this.pos = start;
   417→        return null;
   418→      }
   419→
   420→      this.advance(); // '('
   421→
   422→      // 공백
   423→      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   424→        this.advance();
   425→      }
   426→
   427→      // v 또는 python 확인
   428→      let mode: 'v' | 'python' | null = null;
   429→
   430→      if (this.peek() === 'v' && (this.peek(1) === ')' || this.isWhitespace(this.peek(1)))) {
   431→        mode = 'v';
   432→        this.advance();
   433→      } else if (
   434→        this.peek() === 'p' &&
   435→        this.peek(1) === 'y' &&
   436→        this.peek(2) === 't' &&
   437→        this.peek(3) === 'h' &&
   438→        this.peek(4) === 'o' &&
   439→        this.peek(5) === 'n'
   440→      ) {
   441→        mode = 'python';
   442→        this.advance();
   443→        this.advance();
   444→        this.advance();
   445→        this.advance();
   446→        this.advance();
   447→        this.advance();
   448→      }
   449→
   450→      if (!mode) {
   451→        // 유효한 모드가 아니면 다시 돌아가기
   452→        this.pos = start;
   453→        return null;
   454→      }
   455→
   456→      // 공백 및 ) 확인
   457→      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   458→        this.advance();
