/**
 * FreeLang Nexus - Bus Terminal (@call) 테스트
 *
 * @call 지시문으로 외부 언어 라이브러리를 호출하는 기능 검증
 * python / rust / go / julia / js / c / cpp 7개 언어 지원
 */

import { NexusLexer } from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';
import { TokenType } from '../src/nexus/lexer/token';

function lex(code: string) {
  return new NexusLexer(code).tokenize();
}

function parse(code: string) {
  const tokens = lex(code);
  return new NexusParser(tokens).parse();
}

function compile(code: string): string {
  const ast = parse(code);
  return new NexusCodegen().generate(ast).c;
}

// ─── Lexer: @call 토큰 인식 ──────────────────────────────────────────────────

describe('Bus Terminal - Lexer (@call 토큰)', () => {
  test('Test 1: @call python:numpy CALL_DIRECTIVE 토큰 생성', () => {
    const tokens = lex('@call python:numpy\n');
    const callTok = tokens.find(t => t.type === TokenType.CALL_DIRECTIVE);
    expect(callTok).toBeDefined();
    expect(callTok!.value).toBe('@call python:numpy');
  });

  test('Test 2: @call rust:rand 0.8 - 버전 포함 토큰', () => {
    const tokens = lex('@call rust:rand 0.8\n');
    const callTok = tokens.find(t => t.type === TokenType.CALL_DIRECTIVE);
    expect(callTok).toBeDefined();
    expect(callTok!.value).toBe('@call rust:rand 0.8');
  });

  test('Test 3: @call python:numpy as np - alias 포함 토큰', () => {
    const tokens = lex('@call python:numpy as np\n');
    const callTok = tokens.find(t => t.type === TokenType.CALL_DIRECTIVE);
    expect(callTok!.value).toBe('@call python:numpy as np');
  });

  test('Test 4: @call go:github.com/gin-gonic/gin - 경로 패키지', () => {
    const tokens = lex('@call go:github.com/gin-gonic/gin\n');
    const callTok = tokens.find(t => t.type === TokenType.CALL_DIRECTIVE);
    expect(callTok!.value).toBe('@call go:github.com/gin-gonic/gin');
  });

  test('Test 5: @mode 토큰과 @call 토큰 함께 렉싱', () => {
    const tokens = lex('@mode(v)\n@call python:numpy\n');
    const modeTok = tokens.find(t => t.type === TokenType.MODE_MARKER);
    const callTok = tokens.find(t => t.type === TokenType.CALL_DIRECTIVE);
    expect(modeTok).toBeDefined();
    expect(callTok).toBeDefined();
  });
});

// ─── Parser: ExternCall AST 노드 ─────────────────────────────────────────────

describe('Bus Terminal - Parser (ExternCall AST)', () => {
  test('Test 6: @call python:numpy → ExternCall AST', () => {
    const ast = parse('@mode(v)\n@call python:numpy\n');
    const node = ast.body.find((n: any) => n.type === 'ExternCall') as any;
    expect(node).toBeDefined();
    expect(node.lang).toBe('python');
    expect(node.package).toBe('numpy');
    expect(node.version).toBeUndefined();
    expect(node.alias).toBeUndefined();
  });

  test('Test 7: @call python:numpy 1.24 → version 파싱', () => {
    const ast = parse('@mode(v)\n@call python:numpy 1.24\n');
    const node = ast.body.find((n: any) => n.type === 'ExternCall') as any;
    expect(node.version).toBe('1.24');
  });

  test('Test 8: @call python:numpy as np → alias 파싱', () => {
    const ast = parse('@mode(v)\n@call python:numpy as np\n');
    const node = ast.body.find((n: any) => n.type === 'ExternCall') as any;
    expect(node.alias).toBe('np');
    expect(node.package).toBe('numpy');
  });

  test('Test 9: @call rust:rand 0.8 → rust lang 파싱', () => {
    const ast = parse('@mode(v)\n@call rust:rand 0.8\n');
    const node = ast.body.find((n: any) => n.type === 'ExternCall') as any;
    expect(node.lang).toBe('rust');
    expect(node.package).toBe('rand');
    expect(node.version).toBe('0.8');
  });

  test('Test 10: @call go:github.com/gin-gonic/gin → go lang 파싱', () => {
    const ast = parse('@mode(v)\n@call go:github.com/gin-gonic/gin\n');
    const node = ast.body.find((n: any) => n.type === 'ExternCall') as any;
    expect(node.lang).toBe('go');
    expect(node.package).toBe('github.com/gin-gonic/gin');
  });

  test('Test 11: 여러 @call 지시문 파싱', () => {
    const ast = parse(`@mode(v)
@call python:numpy
@call rust:rand 0.8
@call go:github.com/gin-gonic/gin
`);
    const calls = ast.body.filter((n: any) => n.type === 'ExternCall') as any[];
    expect(calls.length).toBe(3);
    expect(calls[0].lang).toBe('python');
    expect(calls[1].lang).toBe('rust');
    expect(calls[2].lang).toBe('go');
  });

  test('Test 12: @call + 함수 정의 혼합 파싱', () => {
    const ast = parse(`@mode(v)
@call python:numpy
fn main() -> i64 {
  return 0
}
`);
    const call = ast.body.find((n: any) => n.type === 'ExternCall') as any;
    const fn_ = ast.body.find((n: any) => n.type === 'VFunction') as any;
    expect(call).toBeDefined();
    expect(fn_).toBeDefined();
    expect(fn_.name).toBe('main');
  });
});

// ─── Codegen: 언어별 stub 생성 ───────────────────────────────────────────────

describe('Bus Terminal - Codegen (Python stub)', () => {
  test('Test 13: python:numpy → Python.h include + init 함수', () => {
    const c = compile('@mode(v)\n@call python:numpy\n');
    expect(c).toContain('#include <Python.h>');
    expect(c).toContain('__fl_py_mod_numpy');
    expect(c).toContain('__fl_py_init_numpy');
    expect(c).toContain('PyImport_ImportModule("numpy")');
  });

  test('Test 14: python:numpy as np → alias 기반 변수명', () => {
    const c = compile('@mode(v)\n@call python:numpy as np\n');
    expect(c).toContain('__fl_py_mod_np');
    expect(c).toContain('__fl_py_init_np');
  });

  test('Test 15: python stub → pip install 안내 주석 포함', () => {
    const c = compile('@mode(v)\n@call python:numpy 1.24\n');
    expect(c).toContain('pip install numpy');
    expect(c).toContain('1.24');
  });
});

describe('Bus Terminal - Codegen (Rust stub)', () => {
  test('Test 16: rust:rand → cbindgen 안내 + bindings.h include', () => {
    const c = compile('@mode(v)\n@call rust:rand 0.8\n');
    expect(c).toContain('rand_bindings.h');
    expect(c).toContain('cbindgen');
    expect(c).toContain('cargo');
  });
});

describe('Bus Terminal - Codegen (Go stub)', () => {
  test('Test 17: go:github.com/gin-gonic/gin → c-shared 안내', () => {
    const c = compile('@mode(v)\n@call go:github.com/gin-gonic/gin\n');
    expect(c).toContain('-buildmode=c-shared');
    expect(c).toContain('libgin.h');
  });
});

describe('Bus Terminal - Codegen (Julia stub)', () => {
  test('Test 18: julia:Flux → julia.h + jl_init', () => {
    const c = compile('@mode(v)\n@call julia:Flux\n');
    expect(c).toContain('#include <julia.h>');
    expect(c).toContain('jl_init()');
    expect(c).toContain('using Flux');
  });
});

describe('Bus Terminal - Codegen (C/C++ stub)', () => {
  test('Test 19: c:sqlite3 → #include <sqlite3.h>', () => {
    const c = compile('@mode(v)\n@call c:sqlite3\n');
    expect(c).toContain('#include <sqlite3.h>');
  });

  test('Test 20: cpp:vector → extern "C" 래퍼', () => {
    const c = compile('@mode(v)\n@call cpp:vector\n');
    expect(c).toContain('extern "C"');
    expect(c).toContain('#include <vector>');
  });
});

// ─── 통합: @call + 함수 코드젠 ───────────────────────────────────────────────

describe('Bus Terminal - 통합 (함수 + @call)', () => {
  test('Test 21: @call python:numpy + fn main() 혼합 컴파일', () => {
    const c = compile(`@mode(v)
@call python:numpy
fn main() -> i64 {
  let x = 42
  return x
}
`);
    expect(c).toContain('#include <Python.h>');
    expect(c).toContain('long long main()');
    expect(c).toContain('return x;');
  });

  test('Test 22: 여러 @call + 함수 혼합 컴파일 - 순서 보장', () => {
    const c = compile(`@mode(v)
@call python:numpy
@call c:sqlite3
fn add(a: i64, b: i64) -> i64 {
  return a + b
}
`);
    const pyIdx = c.indexOf('Python.h');
    const sqlIdx = c.indexOf('sqlite3.h');
    const fnIdx = c.indexOf('long long add(');
    // @call stub이 함수보다 먼저 나와야 함
    expect(pyIdx).toBeLessThan(fnIdx);
    expect(sqlIdx).toBeLessThan(fnIdx);
  });

  test('Test 23: Python 코드젠도 import 생성', () => {
    const tokens = new NexusLexer('@mode(v)\n@call python:numpy as np\n').tokenize();
    const ast = new NexusParser(tokens).parse();
    const result = new NexusCodegen().generate(ast);
    expect(result.python).toContain('import numpy as np');
  });
});

