/**
 * FreeLang Nexus - 런타임 실행기
 * 생성된 C/Python 코드를 컴파일하고 실행
 */

import { execSync, spawnSync, SpawnSyncReturns } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import { CodegenResult } from '../codegen/nexus-codegen';

export interface RunResult {
  cOutput: string;      // C 실행 결과 (stdout)
  pythonOutput: string; // Python 실행 결과 (stdout)
  errors: string[];     // 컴파일/실행 에러 목록
}

export class NexusRunner {
  private ccCache: string | null = null;

  /**
   * CodegenResult 전체 실행 (C + Python 모두)
   */
  run(result: CodegenResult): RunResult {
    const errors: string[] = [];
    let cOutput = '';
    let pythonOutput = '';

    // C 코드 실행
    if (result.c && result.c.trim()) {
      try {
        cOutput = this.runC(result.c);
      } catch (e) {
        errors.push(`C 컴파일/실행 에러: ${(e as Error).message}`);
      }
    }

    // Python 코드 실행
    if (result.python && result.python.trim()) {
      try {
        pythonOutput = this.runPython(result.python);
      } catch (e) {
        errors.push(`Python 실행 에러: ${(e as Error).message}`);
      }
    }

    return { cOutput, pythonOutput, errors };
  }

  /**
   * C 코드 실행
   * 임시 파일 → 컴파일 → 실행 → 정리
   */
  runC(cCode: string): string {
    const cFile = this.tmpFile('.c');
    const binFile = this.tmpFile('');

    try {
      // C 코드를 임시 파일에 저장
      fs.writeFileSync(cFile, cCode, 'utf-8');

      // 컴파일 (gcc 또는 clang)
      const cc = this.detectCC();
      try {
        execSync(`${cc} -o ${binFile} ${cFile}`, {
          stdio: 'pipe',
          encoding: 'utf-8',
        });
      } catch (e) {
        throw new Error(`컴파일 실패 (${cc}): ${(e as Error).message}`);
      }

      // 바이너리 실행
      const result: SpawnSyncReturns<string> = spawnSync(binFile, [], {
        encoding: 'utf-8',
        stdio: 'pipe',
      });

      if (result.error) {
        throw new Error(`실행 실패: ${result.error.message}`);
      }

      return result.stdout || '';
    } finally {
      // 임시 파일 정리
      try {
        if (fs.existsSync(cFile)) fs.unlinkSync(cFile);
        if (fs.existsSync(binFile)) fs.unlinkSync(binFile);
      } catch (e) {
        // 정리 실패는 무시
      }
    }
  }

  /**
   * Python 코드 실행
   * 임시 파일 → python3 실행 → 정리
   */
  runPython(pyCode: string): string {
    const pyFile = this.tmpFile('.py');

    try {
      // Python 코드를 임시 파일에 저장
      fs.writeFileSync(pyFile, pyCode, 'utf-8');

      // python3 실행
      const result: SpawnSyncReturns<string> = spawnSync('python3', [pyFile], {
        encoding: 'utf-8',
        stdio: 'pipe',
      });

      if (result.error) {
        throw new Error(`Python 실행 실패: ${result.error.message}`);
      }

      return result.stdout || '';
    } finally {
      // 임시 파일 정리
      try {
        if (fs.existsSync(pyFile)) fs.unlinkSync(pyFile);
      } catch (e) {
        // 정리 실패는 무시
      }
    }
  }

  /**
   * 컴파일러 감지 (gcc 또는 clang)
   * Termux 환경에서는 clang을 기본으로 사용하는 경우가 많음
   */
  private detectCC(): string {
    if (this.ccCache) {
      return this.ccCache;
    }

    // 먼저 gcc 확인
    try {
      execSync('gcc --version', { stdio: 'pipe' });
      this.ccCache = 'gcc';
      return 'gcc';
    } catch (e) {
      // gcc 실패
    }

    // clang 확인
    try {
      execSync('clang --version', { stdio: 'pipe' });
      this.ccCache = 'clang';
      return 'clang';
    } catch (e) {
      // clang 실패
    }

    // 기본값: gcc (찾기 실패해도 시도)
    this.ccCache = 'gcc';
    return 'gcc';
  }

  /**
   * 임시 파일 경로 생성
   * /tmp/nexus_TIMESTAMP.ext 형식
   */
  private tmpFile(ext: string): string {
    const timestamp = Date.now();
    const random = Math.random().toString(36).substring(2, 8);
    const filename = `nexus_${timestamp}_${random}${ext}`;
    return path.join(os.tmpdir(), filename);
  }
}

/**
 * FreeLang Nexus - 코드 생성기
 * AST → C 코드 (V 모드) + Python 코드 (Python 모드)
 */

import * as AST from '../parser/ast';

export interface CodegenResult {
  c: string;       // V 모드 함수들 → C 코드
  python: string;  // Python 모드 함수들 → Python 코드
  mixed: string;   // 두 코드 주석으로 구분 (디버그용)
}

export class NexusCodegen {
  private cLines: string[] = [];
  private pyLines: string[] = [];
  private indentLevel: number = 0;

  /**
   * V 모드 내장 함수 처리
   */
  private readonly V_BUILTINS = new Set([
    'println', 'print', 'len', 'to_string', 'int_cast',
    // 수학
    'abs', 'min', 'max', 'sqrt', 'pow', 'floor', 'ceil',
    // 문자열
    'str_len', 'str_contains', 'str_concat', 'str_eq',
    // 타입 변환
    'float_cast', 'bool_cast',
  ]);

